package run.ikaros.finance; import java.math.BigDecimal; import java.time.Instant; import java.time.YearMonth; import java.time.ZoneOffset; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @Service public class FinanceStatisticsService{private final FinanceTransactionRepository transactions;private final FinanceLedgerAccessService access;public FinanceStatisticsService(FinanceTransactionRepository t,FinanceLedgerAccessService a){transactions=t;access=a;}public Mono<MonthlyStatisticsView> month(UUID actor,UUID ledgerId,YearMonth month){return access.access(actor,ledgerId).flatMap(role->{Instant from=month.atDay(1).atStartOfDay().toInstant(ZoneOffset.UTC),to=month.plusMonths(1).atDay(1).atStartOfDay().toInstant(ZoneOffset.UTC);return transactions.findAllByLedgerIdAndOccurredAtGreaterThanEqualAndOccurredAtLessThanOrderByOccurredAtDesc(ledgerId,from,to).collectList().map(xs->{BigDecimal income=BigDecimal.ZERO,expense=BigDecimal.ZERO,transfer=BigDecimal.ZERO;for(FinanceTransactionEntity tx:xs){if(tx.type()==TransactionType.INCOME)income=income.add(tx.amount());else if(tx.type()==TransactionType.EXPENSE)expense=expense.add(tx.amount());else if(tx.type()==TransactionType.TRANSFER)transfer=transfer.add(tx.amount());}return new MonthlyStatisticsView(month,income,expense,transfer,xs.size());});});}public Flux<TransactionView> search(UUID actor,UUID ledgerId,String query){String q=query==null?"":query.toLowerCase();return access.access(actor,ledgerId).flatMapMany(role->transactions.findAllByLedgerIdOrderByOccurredAtDesc(ledgerId).take(100).filter(t->(t.payee()!=null&&t.payee().toLowerCase().contains(q))||(t.note()!=null&&t.note().toLowerCase().contains(q))).map(this::view));}private TransactionView view(FinanceTransactionEntity t){return new TransactionView(t.id(),t.ledgerId(),t.type(),t.accountId(),t.targetAccountId(),t.amount(),t.currency(),t.categoryId(),t.payee(),t.note(),t.occurredAt(),t.status(),t.source());}}
